/* kn_selftest.c — self-test registry and runners (BOOTSTRAP.md §7.9).
 * Contract in kn_selftest.h.
 *
 * The vector tests re-run the SAME known-answer vectors as the unit tests
 * (streamer/src/knfec_kat_vectors.h, knsrtp_kat_vectors.h — generated by the
 * independent Python references, precedence documented in those files).
 * Unit tests prove the code at build time on the host; self-tests prove the
 * SHIPPED BINARY on the target machine — different questions, same vectors.
 * "If the C code disagrees with a vector, the C code is wrong."
 *
 * Platform shims follow the knlog.c/kn_diag.c pattern: Win32 primary,
 * POSIX so the offline vectors also run on the host.
 */
#ifndef _WIN32
/* See kn_diag.c: feature macro must precede every system include. */
#if !defined(_POSIX_C_SOURCE) || (_POSIX_C_SOURCE < 200809L)
#undef _POSIX_C_SOURCE
#define _POSIX_C_SOURCE 200809L
#endif
#endif

