/* The bundled clip for decode.synthetic (§7.9 "decode a BUNDLED .264").
 * Generated by tools/make_synthetic_clip.py from artifacts/synthetic.264.
 * Unconditional include: the stub build compiles the embedded path (it is
 * only reached when kn_decode_available() is true) — keeps one code path. */
#include "kn_synthetic_clip.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

