#  include <unistd.h>       /* readlink for the exe-dir clip probe */
#endif

#ifdef _WIN32
#  define WIN32_LEAN_AND_MEAN
#  include <windows.h>
#  include <mmsystem.h>          /* timeBeginPeriod/timeEndPeriod (winmm) */
#  ifndef ENABLE_VIRTUAL_TERMINAL_PROCESSING
#    define ENABLE_VIRTUAL_TERMINAL_PROCESSING 0x0004u  /* not in Win7 SDK headers */
#  endif
static long long st_mono_ms(void)
{
    static LARGE_INTEGER freq;
    LARGE_INTEGER pc;
    if (!freq.QuadPart) QueryPerformanceFrequency(&freq);
    QueryPerformanceCounter(&pc);
    if (!freq.QuadPart) return 0;
    return (long long)((double)pc.QuadPart * 1000.0 / (double)freq.QuadPart);
}
static long long st_wall_us(void)
{
    FILETIME ft;
    ULARGE_INTEGER u;
    GetSystemTimeAsFileTime(&ft);
    u.LowPart = ft.dwLowDateTime;
    u.HighPart = ft.dwHighDateTime;
    return (long long)(u.QuadPart / 10ULL);            /* 100 ns -> us */
}
#else
#  include <time.h>
static long long st_mono_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}
#endif

/* ------------------------------------------------------- vector check tally */

typedef struct {
    int  checks;
    int  failures;
    char first_fail[KN_ST_REASON_MAX - 64];
} st_tally;

#define STV(t, cond, name)                                                \
    do {                                                                  \
        (t).checks++;                                                     \
        if (!(cond)) {                                                    \
            (t).failures++;                                               \
            if (!(t).first_fail[0])                                       \
                snprintf((t).first_fail, sizeof (t).first_fail, "%s", (name)); \
        }                                                                 \
    } while (0)

static void finish_tally(kn_st_result *r, const st_tally *t, const char *evidence_extra)
{
    r->checks = t->checks;
    r->failures = t->failures;
    if (t->failures == 0) {
        r->status = KN_ST_OK;
        snprintf(r->reason, sizeof r->reason, "all %d known-answer checks passed",
                 t->checks);
    } else {
        r->status = KN_ST_FAILED;
        /* %.64s + shortened text keep the worst case (11+11+26+64+52 < 192)
         * provably inside KN_ST_REASON_MAX for -Wformat-truncation */
        snprintf(r->reason, sizeof r->reason,
                 "%d/%d KAT checks FAILED (first: %.64s) — shipped binary "
                 "disagrees with reference vectors",
                 t->failures, t->checks, t->first_fail);
    }
    if (evidence_extra && evidence_extra[0])
        snprintf(r->evidence, sizeof r->evidence,
                 "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\",%s}",
                 t->checks, t->failures, t->first_fail, evidence_extra);
    else
        snprintf(r->evidence, sizeof r->evidence,
                 "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\"}",
                 t->checks, t->failures, t->first_fail);
}

/* ============================================================ fec.vectors */

static int st_fec_vectors(kn_st_result *r)
{
    st_tally t;
    uint8_t p;
    int i, d, b, rc;

    memset(&t, 0, sizeof t);

    /* GF(2^8) generator powers + 0x11d wrap (nvst.rs:3717-3742) */
    p = 1;
    for (i = 0; i < 16; ++i) {
        STV(t, p == k_kat_gf_exp[i], "gf exp power");
        p = kn_gf_mul(p, 2);
    }
    STV(t, k_kat_gf_exp[8] == k_kat_gf_exp_wrap, "0x11d wrap golden");

    /* gf_mul / gf_inv goldens */
    for (i = 0; i < K_KAT_GF_MUL_COUNT; ++i)
        STV(t, kn_gf_mul(k_kat_gf_mul[i][0], k_kat_gf_mul[i][1]) == k_kat_gf_mul[i][2],
            "gf_mul golden");
    for (i = 0; i < (int)(sizeof k_kat_gf_inv_inputs / sizeof k_kat_gf_inv_inputs[0]); ++i)
        STV(t, kn_gf_inv(k_kat_gf_inv_inputs[i]) == k_kat_gf_inv[i], "gf_inv golden");

    /* Cauchy coefficients — PITFALL #3 (BOOTSTRAP §8): NOT Vandermonde */
    for (d = 0; d < 5; ++d)
        for (i = 0; i < 2; ++i) {
            uint8_t c = 0;
            STV(t, kn_fec_cauchy_coeff((unsigned)d, (unsigned)i, 2, &c) == 0 &&
                   c == k_kat_cauchy_5_2[d][i], "cauchy 5+2 coeff");
        }
    for (d = 0; d < 3; ++d) {
        uint8_t c = 0;
        STV(t, kn_fec_cauchy_coeff((unsigned)d, 0, 1, &c) == 0 &&
               c == k_kat_cauchy_3_1[d][0], "cauchy 3+1 coeff");
    }

    /* parity_shards is COMPUTED: ceil(data*pct/100) — PITFALL #11 */
    STV(t, kn_fec_parity_count(10, 20) == 2, "parity ceil(10,20)=2");
    STV(t, kn_fec_parity_count(7, 20) == 2, "parity ceil(7,20)=2");
    STV(t, kn_fec_parity_count(12, 25) == 3, "parity ceil(12,25)=3");
    STV(t, kn_fec_parity_count(5, 0) == 0, "parity pct 0 = inactive");

    /* nvst.rs:13239 reference vector: 5+2 shards x 97 B, encode + reconstruct */
    {
        static uint8_t data[5][97], parity[2][97], rec1[97], rec3[97];
        uint8_t *dptr[5], *pptr[2], *shards[7], *out[5];
        size_t dlens[5], slens[7];
        uint8_t scratch[512];
        int s;
        for (s = 0; s < 5; ++s) {
            for (b = 0; b < 97; ++b) data[s][b] = (uint8_t)(s * 41 + b * 17);
            dptr[s] = data[s];
            dlens[s] = 97;
        }
        pptr[0] = parity[0];
        pptr[1] = parity[1];
        rc = kn_fec_encode((const uint8_t *const *)dptr, dlens, 5, pptr, 2, 97);
        STV(t, rc == 0, "nvst vector encode rc");
        STV(t, memcmp(parity[0], k_kat_nvst_parity_0, 97) == 0, "nvst parity[0] golden");
        STV(t, memcmp(parity[1], k_kat_nvst_parity_1, 97) == 0, "nvst parity[1] golden");
        shards[0] = data[0]; slens[0] = 97;
        shards[1] = NULL;    slens[1] = 0;
        shards[2] = data[2]; slens[2] = 97;
        shards[3] = NULL;    slens[3] = 0;
        shards[4] = data[4]; slens[4] = 97;
        shards[5] = parity[0]; slens[5] = 97;
        shards[6] = parity[1]; slens[6] = 97;
        memset(out, 0, sizeof out);
        out[1] = rec1;
        out[3] = rec3;
        rc = kn_fec_reconstruct(shards, slens, 5, 2, 97, scratch, sizeof scratch,
                                (uint8_t *const *)out);
        STV(t, rc == 2, "nvst vector reconstructs 2 shards");
        STV(t, memcmp(rec1, data[1], 97) == 0, "shard 1 restored exactly");
        STV(t, memcmp(rec3, data[3], 97) == 0, "shard 3 restored exactly");
    }

    /* short-shard zero padding (nvst.rs:3852, 3867-3873) */
    {
        uint8_t d0[8], d1[5], d2[8], par[8], rec1[8];
        uint8_t *dptr[3], *pptr[1], *shards[4], *out[3];
        size_t dlens[3], slens[4];
        uint8_t scratch[64];
        for (b = 0; b < 8; ++b) { d0[b] = (uint8_t)(b * 29); d2[b] = (uint8_t)(106 + b * 29); }
        for (b = 0; b < 5; ++b) d1[b] = (uint8_t)(53 + b * 29);
        dptr[0] = d0; dptr[1] = d1; dptr[2] = d2;
        dlens[0] = 8; dlens[1] = 5; dlens[2] = 8;
        pptr[0] = par;
        rc = kn_fec_encode((const uint8_t *const *)dptr, dlens, 3, pptr, 1, 8);
        STV(t, rc == 0, "short-shard encode rc");
        STV(t, memcmp(par, k_kat_short_parity, 8) == 0, "short-shard parity golden");
        shards[0] = d0;  slens[0] = 8;
        shards[1] = NULL; slens[1] = 0;
        shards[2] = d2;  slens[2] = 8;
        shards[3] = par; slens[3] = 8;
        out[0] = NULL; out[1] = rec1; out[2] = NULL;
        rc = kn_fec_reconstruct(shards, slens, 3, 1, 8, scratch, sizeof scratch,
                                (uint8_t *const *)out);
        STV(t, rc == 1, "short-shard reconstruct rc");
        STV(t, memcmp(rec1, k_kat_short_data1_padded, 8) == 0,
            "reconstructed shard = original + zero padding");
    }

    /* wide block n=12 p=4 (max realistic Mjolnir shape) */
    {
        static uint8_t data[K_KAT_WIDE_N][K_KAT_WIDE_LEN];
        static uint8_t parity[K_KAT_WIDE_P][K_KAT_WIDE_LEN];
        uint8_t *dptr[K_KAT_WIDE_N], *pptr[K_KAT_WIDE_P];
        const uint8_t *goldens[K_KAT_WIDE_P];
        size_t dlens[K_KAT_WIDE_N];
        goldens[0] = k_kat_wide_parity_0;
        goldens[1] = k_kat_wide_parity_1;
        goldens[2] = k_kat_wide_parity_2;
        goldens[3] = k_kat_wide_parity_3;
        for (d = 0; d < K_KAT_WIDE_N; ++d) {
            for (b = 0; b < (int)K_KAT_WIDE_LEN; ++b)
                data[d][b] = (uint8_t)(d * 53 + b * 29 + d * b * 7);
            dptr[d] = data[d];
            dlens[d] = K_KAT_WIDE_LEN;
            if (d < K_KAT_WIDE_P) pptr[d] = parity[d];
        }
        rc = kn_fec_encode((const uint8_t *const *)dptr, dlens, K_KAT_WIDE_N,
                           pptr, K_KAT_WIDE_P, K_KAT_WIDE_LEN);
        STV(t, rc == 0, "wide encode rc");
        for (d = 0; d < K_KAT_WIDE_P; ++d)
            STV(t, memcmp(parity[d], goldens[d], K_KAT_WIDE_LEN) == 0,
                "wide parity golden (n=12 p=4)");
    }

    finish_tally(r, &t, "\"vectors\":\"knfec_kat_vectors.h (tools/fec_reference.py)\"");
    return 0;
}

/* =========================================================== srtp.vectors */

static int st_srtp_vectors(kn_st_result *r)
{
    st_tally t;
    kn_aes128_ctx actx;
    uint8_t out[96], ck[16], cs[14], blk[16], auth[96], a20[20], sk[16], ss[14];
    uint8_t iv[16], g[12], sg[12];
    int i, rc;

    memset(&t, 0, sizeof t);

    /* AES-128 block goldens: FIPS-197 C.1 + SP800-38A F.1.1 (in-place) */
    kn_aes128_init(&actx, k_kat_aes_fips197_key);
    kn_aes128_encrypt(&actx, k_kat_aes_fips197_pt, out);
    STV(t, memcmp(out, k_kat_aes_fips197_ct, 16) == 0, "FIPS-197 C.1 AES-128");
    memcpy(out, k_kat_aes_sp80038a_pt, 16);
    kn_aes128_init(&actx, k_kat_aes_sp80038a_key);
    kn_aes128_encrypt(&actx, out, out);
    STV(t, memcmp(out, k_kat_aes_sp80038a_ct, 16) == 0, "SP800-38A F.1.1 in-place");

    /* RFC 3711 B.2 keystream, incl. the FEFF->FF00 counter carry */
    for (i = 0; i < 6; ++i) {
        kn_srtp_aes_cm_keystream_block(k_kat_b2_key, k_kat_b2_offset,
                                       k_kat_b2_idx[i], out);
        STV(t, memcmp(out, k_kat_b2_ks[i], 16) == 0, "RFC3711 B.2 keystream block");
    }

    /* RFC 3711 B.3 KDF + the nvst cross-implementation derivations */
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == 0 &&
           memcmp(ck, k_kat_b3_cipher_key, 16) == 0, "B.3 cipher key (label 0x00)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_SALT, cs, 14) == 0 &&
           memcmp(cs, k_kat_b3_cipher_salt, 14) == 0, "B.3 cipher salt (label 0x02)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_SALT, blk, 16) == 0 &&
           memcmp(blk, k_kat_b3_salt_block0, 16) == 0, "B.3 salt keystream block 0");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_AUTH_KEY, auth, K_KAT_B3_AUTH_KEY_LEN) == 0 &&
           memcmp(auth, k_kat_b3_auth_key, K_KAT_B3_AUTH_KEY_LEN) == 0,
        "B.3 auth key 94B (label 0x01)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_AUTH_KEY, a20, 20) == 0 &&
           memcmp(a20, k_kat_auth20, 20) == 0, "auth20 prefix (nvst.rs:2888)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          0x03, sk, 16) == 0 &&
           memcmp(sk, k_kat_srtcp_key, 16) == 0, "SRTCP key (label 0x03)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          0x05, ss, 14) == 0 &&
           memcmp(ss, k_kat_srtcp_salt, 14) == 0, "SRTCP salt (label 0x05)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 12,
                          KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == 0,
        "12-byte salt accepted (GCM profile path)");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 15,
                          KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == -1, "salt_len 15 rejected");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_CIPHER_KEY, ck, 0) == -1, "out_len 0 rejected");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                          KN_SRTP_LABEL_CIPHER_KEY, NULL, 16) == -1, "NULL out rejected");
    STV(t, kn_srtp_kdf128(k_kat_b3_master, NULL, 14,
                          KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == -1, "NULL salt rejected");

    /* IV builders (nvst.rs:2902 / RFC 7714 9.1 / 9.2) */
    kn_srtp_aes_cm_iv(k_kat_iv_salt14, K_KAT_IV_SSRC, K_KAT_IV_PKT_INDEX, iv);
    STV(t, memcmp(iv, k_kat_iv_cm, 16) == 0, "AES-CM IV (nvst.rs:2902)");
    kn_srtp_gcm_iv(k_kat_iv_salt12, K_KAT_IV_SSRC, K_KAT_IV_ROC, K_KAT_IV_SEQ, g);
    STV(t, memcmp(g, k_kat_iv_gcm, 12) == 0, "GCM IV (RFC 7714 9.1)");
    kn_srtcp_gcm_iv(k_kat_iv_salt12, K_KAT_IV_SSRC, K_KAT_SRTCP_INDEX, sg);
    STV(t, memcmp(sg, k_kat_iv_srtcp_gcm, 12) == 0, "SRTCP GCM IV (RFC 7714 9.2)");

    /* keystream xor: B.2 block 0, round-trip, split resume, zero-length */
    {
        static uint8_t buf[1000], orig[1000], a[1000], b2[1000], expect[16];
        for (i = 0; i < 1000; ++i) {
            unsigned char v = (unsigned char)(i * 31 + 7);
            buf[i] = v;
            orig[i] = v;
        }
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, buf, sizeof buf);
        STV(t, memcmp(buf, orig, sizeof buf) != 0, "keystream xor changes data");
        for (i = 0; i < 16; ++i) expect[i] = (uint8_t)(k_kat_b2_ks[0][i] ^ orig[i]);
        STV(t, memcmp(buf, expect, 16) == 0, "xor matches RFC3711 B.2 block 0");
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, buf, sizeof buf);
        STV(t, memcmp(buf, orig, sizeof buf) == 0, "round-trip restores plaintext");
        memcpy(a, orig, sizeof a);
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, a, sizeof a);
        memcpy(b2, orig, sizeof b2);
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, b2, 400);
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 25, b2 + 400, 600);
        STV(t, memcmp(a, b2, sizeof a) == 0, "split keystream == continuous (block 25)");
    }

    /* SHA-1: RFC 3174 TEST1/2/4 (+empty). TEST3 (1M x 'a') is deliberately
     * EXCLUDED from the self-test: it is covered by the unit test, and on the
     * 2-core target the self-test budget is ~1 s for ALL tests (§7.9). */
    kn_sha1("abc", 3, out);
    STV(t, memcmp(out, k_kat_sha1_abc, 20) == 0, "SHA-1 RFC3174 TEST1");
    kn_sha1("", 0, out);
    STV(t, memcmp(out, k_kat_sha1_empty, 20) == 0, "SHA-1 empty");
    kn_sha1(k_kat_sha1_t2_msg, sizeof k_kat_sha1_t2_msg, out);
    STV(t, memcmp(out, k_kat_sha1_t2, 20) == 0, "SHA-1 TEST2 (56B padding edge)");
    {
        kn_sha1_ctx sc;
        int j;
        kn_sha1_init(&sc);
        for (j = 0; j < 10; ++j)
            kn_sha1_update(&sc, k_kat_sha1_t4_msg, sizeof k_kat_sha1_t4_msg);
        kn_sha1_final(&sc, out);
        STV(t, memcmp(out, k_kat_sha1_t4, 20) == 0, "SHA-1 TEST4 (streaming)");
    }

    /* HMAC-SHA1: RFC 2202 cases 1-7 + incremental == one-shot */
    for (i = 0; i < 7; ++i) {
        kn_hmac_sha1(k_kat_hmac_blob + k_kat_hmac_key_off[i], k_kat_hmac_key_len[i],
                     k_kat_hmac_blob + k_kat_hmac_data_off[i], k_kat_hmac_data_len[i],
                     out);
        STV(t, memcmp(out, k_kat_hmac_digest[i], 20) == 0, "HMAC-SHA1 RFC2202 case");
    }
    {
        kn_hmac_sha1_ctx hc;
        kn_hmac_sha1_init(&hc, k_kat_hmac_blob + k_kat_hmac_key_off[0],
                          k_kat_hmac_key_len[0]);
        kn_hmac_sha1_update(&hc, "Hi ", 3);
        kn_hmac_sha1_update(&hc, "There", 5);
        kn_hmac_sha1_final(&hc, out);
        STV(t, memcmp(out, k_kat_hmac_digest[0], 20) == 0, "incremental HMAC == one-shot");
    }

    /* constant-time compare (PITFALL #17) */
    {
        uint8_t x[10], y[10];
        memset(x, 0x42, sizeof x);
        memcpy(y, x, sizeof y);
        STV(t, kn_ct_memeq(x, y, sizeof x) == 1, "ct_memeq equal");
        y[9] ^= 0xFF;
        STV(t, kn_ct_memeq(x, y, sizeof x) == 0, "ct_memeq differs at last byte");
    }

    /* protect/unprotect goldens (python reference) + tamper paths */
    {
        uint8_t pkt[128], saved[128];
        size_t plain_len = 0;
        const uint8_t *enc = k_kat_b3_cipher_key;
        const uint8_t *csalt = k_kat_b3_cipher_salt;
        const uint8_t *authk = k_kat_auth20;

        memcpy(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN);
        rc = kn_srtp_protect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN, K_KAT_P2_PAYLOAD_OFF,
                                     K_KAT_P2_SSRC, K_KAT_P2_PKT_INDEX, enc, authk,
                                     csalt, KN_SRTP_TAG_LEN_80);
        STV(t, rc == 0 && memcmp(pkt, k_kat_p2_protected10,
                                 K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80) == 0,
            "protect matches golden (tag 80)");
        rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                       K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                       K_KAT_P2_PKT_INDEX, enc, authk, csalt,
                                       KN_SRTP_TAG_LEN_80, &plain_len);
        STV(t, rc == 0 && plain_len == K_KAT_P2_PLAIN_LEN &&
               memcmp(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN) == 0,
            "unprotect restores plaintext");
        memcpy(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN);
        rc = kn_srtp_protect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN, K_KAT_P2_PAYLOAD_OFF,
                                     K_KAT_P2_SSRC, K_KAT_P2_PKT_INDEX, enc, authk,
                                     csalt, KN_SRTP_TAG_LEN_32);
        STV(t, rc == 0 && memcmp(pkt, k_kat_p2_protected4,
                                 K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_32) == 0,
            "protect matches golden (tag 32)");
        memcpy(pkt, k_kat_p2_protected10, sizeof k_kat_p2_protected10);
        pkt[20] ^= 0xFF;
        memcpy(saved, pkt, sizeof k_kat_p2_protected10);
        rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                       K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                       K_KAT_P2_PKT_INDEX, enc, authk, csalt,
                                       KN_SRTP_TAG_LEN_80, &plain_len);
        STV(t, rc == 1, "tampered payload -> AuthenticationFailed");
        STV(t, memcmp(pkt, saved, sizeof k_kat_p2_protected10) == 0,
            "failed auth leaves packet untouched (auth-before-decrypt)");
        memcpy(pkt, k_kat_p2_protected10, sizeof k_kat_p2_protected10);
        pkt[K_KAT_P2_PLAIN_LEN + 3] ^= 0x01;
        rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                       K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                       K_KAT_P2_PKT_INDEX, enc, authk, csalt,
                                       KN_SRTP_TAG_LEN_80, &plain_len);
        STV(t, rc == 1, "tampered tag -> AuthenticationFailed");
        rc = kn_srtp_unprotect_cm_hmac(pkt, 9, K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                       K_KAT_P2_PKT_INDEX, enc, authk, csalt,
                                       KN_SRTP_TAG_LEN_80, &plain_len);
        STV(t, rc == -1, "packet shorter than tag -> -1");
    }

    /* ROC derivation + replay window against the 96-op reference simulation */
    STV(t, kn_srtp_roc_of(0x11234ull) == 1, "roc_of(0x11234)=1");
    STV(t, kn_srtp_roc_of(0xFFFFull) == 0, "roc_of(0xFFFF)=0");
    STV(t, kn_srtp_roc_of(0x100000005ull) == 0x10000u, "roc_of 40-bit");
    {
        kn_srtp_replay w;
        int mism = 0, first_bad = -1;
        char extra[96];
        kn_srtp_replay_init(&w);
        for (i = 0; i < K_KAT_REPLAY_N; ++i) {
            uint64_t idx = 0;
            int grc = kn_srtp_replay_guess(&w, k_kat_replay_seq[i], &idx);
            if (grc != (int)k_kat_replay_guess_rc[i]) {
                mism++; if (first_bad < 0) first_bad = i; continue;
            }
            if (grc != 0) continue;
            if (idx != k_kat_replay_index[i]) {
                mism++; if (first_bad < 0) first_bad = i; continue;
            }
            {
                int crc = kn_srtp_replay_check(&w, idx);
                if (crc != (int)k_kat_replay_check_rc[i]) {
                    mism++; if (first_bad < 0) first_bad = i; continue;
                }
                if (crc == 0) kn_srtp_replay_commit(&w, idx);
            }
        }
        t.checks++;
        if (mism) {
            t.failures++;
            if (!t.first_fail[0])
                snprintf(t.first_fail, sizeof t.first_fail,
                         "replay op %d diverges from reference", first_bad);
        }
        snprintf(extra, sizeof extra, "\"replay_ops\":%d,\"replay_mismatches\":%d",
                 K_KAT_REPLAY_N, mism);
        finish_tally(r, &t, extra);
        return 0;
    }
}

/* ========================================================= clock.resolution */

#ifdef _WIN32
/* Wall-clock update interval: sample GetSystemTimeAsFileTime until it moves,
 * timed with QPC. ~2 samples, worst case ~40 ms at default 15.6 ms granularity. */
static long long wall_tick_us(void)
{
    long long a = st_wall_us(), b;
    long long t0 = st_mono_ms();
    do {
        b = st_wall_us();
        if (st_mono_ms() - t0 > 100) return -1;          /* no tick in 100 ms */
    } while (b == a);
    /* one QPC-ms resolution is enough at this scale; refine with us delta */
    return b - a > 0 ? b - a : 1;
}

static double sleep1_mean_ms(int n)
{
    long long t0, total = 0;
    int i;
    for (i = 0; i < n; ++i) {
        t0 = st_mono_ms();
        Sleep(1);
        total += st_mono_ms() - t0;
    }
    return (double)total / (double)n;
}

static int st_clock_resolution(kn_st_result *r)
{
    st_tally t;
    LARGE_INTEGER qpf;
    long long tick_before, tick_after;
    double sleep_before, sleep_after;
    char extra[256];

    memset(&t, 0, sizeof t);
    QueryPerformanceFrequency(&qpf);
    STV(t, qpf.QuadPart > 0, "QPC available");

    tick_before = wall_tick_us();
    sleep_before = sleep1_mean_ms(8);
    STV(t, timeBeginPeriod(1) == TIMERR_NOERROR, "timeBeginPeriod(1) accepted");
    tick_after = wall_tick_us();
    sleep_after = sleep1_mean_ms(8);
    timeEndPeriod(1);

    STV(t, tick_before > 0 && tick_after > 0, "wall granularity measured");

    if (sleep_after <= 2.6)
        r->status = KN_ST_OK;
    else if (sleep_after < sleep_before - 0.5)
        r->status = KN_ST_DEGRADED;
    else
        r->status = KN_ST_FAILED;
    snprintf(r->reason, sizeof r->reason,
             "Sleep(1) mean %.2f ms -> %.2f ms after timeBeginPeriod(1); "
             "wall tick %lld us -> %lld us",
             sleep_before, sleep_after, tick_before, tick_after);
    snprintf(extra, sizeof extra,
             "\"qpc_hz\":%lld,\"wall_tick_us_before\":%lld,\"wall_tick_us_after\":%lld,"
             "\"sleep1_ms_before\":%.2f,\"sleep1_ms_after\":%.2f",
             (long long)qpf.QuadPart, tick_before, tick_after,
             sleep_before, sleep_after);
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%s\",%s}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}
#else
static int st_clock_resolution(kn_st_result *r)
{
    r->status = KN_ST_SKIPPED;
    snprintf(r->reason, sizeof r->reason,
             "win32-only (timeBeginPeriod); run on the target machine");
    snprintf(r->evidence, sizeof r->evidence, "{\"platform\":\"posix-host\"}");
    return 0;
}
#endif

/* =========================================================== console.host */

#ifdef _WIN32
static int st_console_host(kn_st_result *r)
{
    st_tally t;
    HANDLE hOut;
    HMODULE hk64, hk32;
    char build[32];
    DWORD got;
    DWORD mode = 0;
    int vt_set_ok = 0, vt_set_err = 0;
    int is_char = 0, attr_applied = -1;   /* -1 = not probed */
    char extra[384];

    memset(&t, 0, sizeof t);

    /* D1 evidence #1: ConEmuHk64.dll loaded in-process (BOOTSTRAP §6.2) */
    hk64 = GetModuleHandleW(L"ConEmuHk64.dll");
    hk32 = GetModuleHandleW(L"ConEmuHk32.dll");
    STV(t, 1, "module probe executed");
    got = GetEnvironmentVariableA("ConEmuBuild", build, sizeof build);
    if (got == 0 || got >= sizeof build) snprintf(build, sizeof build, "absent");

    hOut = GetStdHandle(STD_OUTPUT_HANDLE);
    is_char = (hOut != INVALID_HANDLE_VALUE) &&
              (GetFileType(hOut) == FILE_TYPE_CHAR);

    /* VT mode attempt: expected to FAIL with 87 on Win7 conhost; ConEmu's
     * hook parses ANSI regardless — the attempt is evidence, not a fix. */
    if (is_char && GetConsoleMode(hOut, &mode)) {
        if (SetConsoleMode(hOut, mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING)) {
            vt_set_ok = 1;
        } else {
            vt_set_err = (int)GetLastError();
            SetConsoleMode(hOut, mode);       /* restore, best effort */
        }
    }

    /* ANSI attribute write/read-back probe (only possible on a real console).
     * Saves the target cell, writes ESC[91m + marker, reads the attribute
     * back, restores the cell — leaves no visible trace. */
    if (is_char) {
        CONSOLE_SCREEN_BUFFER_INFO sbi;
        if (GetConsoleScreenBufferInfo(hOut, &sbi)) {
            COORD at = sbi.dwCursorPosition;
            CHAR_INFO saved[1];
            DWORD wrote = 0;
            COORD rd_at = at, rd_sz = { 1, 1 };
            SMALL_RECT rd_rect = { 0, 0, 0, 0 };
            WORD attr_before = sbi.wAttributes, attr_after;
            COORD buf_sz = { 1, 1 };

            if (ReadConsoleOutputW(hOut, saved, buf_sz, (COORD){0, 0}, &rd_rect)) {
                rd_rect.Left = rd_rect.Right = at.X;
                rd_rect.Top = rd_rect.Bottom = at.Y;
                attr_before = saved[0].Attributes;
            }
            WriteConsoleA(hOut, "\x1b[91m", 5, &wrote, NULL);
            WriteConsoleA(hOut, "#", 1, &wrote, NULL);
            WriteConsoleA(hOut, "\x1b[0m", 4, &wrote, NULL);
            rd_rect.Left = rd_rect.Right = at.X;
            rd_rect.Top = rd_rect.Bottom = at.Y;
            if (ReadConsoleOutputW(hOut, saved, buf_sz, (COORD){0, 0}, &rd_rect)) {
                attr_after = saved[0].Attributes;
                attr_applied = (attr_after != attr_before ||
                                (attr_after & 0x000Fu) == 0x000Cu ||
                                (attr_after & 0x000Fu) == 0x0004u);
                /* restore: the marker char replaced whatever was there; under
                 * ConEmu the ESC sequence is consumed and '#' lands at `at` */
                WriteConsoleOutputW(hOut, saved, buf_sz, (COORD){0, 0}, &rd_rect);
                (void)rd_at; (void)rd_sz;
            }
            STV(t, 1, "attribute read-back executed");
        } else {
            STV(t, 0, "GetConsoleScreenBufferInfo failed on console handle");
        }
    }

    snprintf(extra, sizeof extra,
             "\"conemu_hk64\":%s,\"conemu_hk32\":%s,\"conemu_build\":\"%s\","
             "\"stdout_is_console\":%s,\"vt_setconsolemode_ok\":%s,\"vt_err\":%d,"
             "\"attr_applied\":\"%s\"",
             hk64 ? "true" : "false", hk32 ? "true" : "false", build,
             is_char ? "true" : "false", vt_set_ok ? "true" : "false", vt_set_err,
             attr_applied < 0 ? "not_probed" : (attr_applied ? "true" : "false"));

    if ((hk64 || hk32) && (attr_applied != 0)) {
        r->status = KN_ST_OK;
        snprintf(r->reason, sizeof r->reason,
                 "ConEmu hook present (build %s); ANSI %s", build,
                 attr_applied > 0 ? "attributes verified" :
                 "not probeable (stdout redirected) — hook is the D1 evidence");
    } else if (attr_applied == 1) {
        r->status = KN_ST_DEGRADED;
        snprintf(r->reason, sizeof r->reason,
                 "ANSI works but ConEmuHk is NOT loaded — unexpected console host");
    } else {
        r->status = KN_ST_FAILED;
        snprintf(r->reason, sizeof r->reason,
                 "D1 VIOLATION: no ConEmu hook and ANSI does not apply — "
                 "ESC bytes will render as glyphs; launch via ConEmu");
    }
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%s\",%s}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}
#else
static int st_console_host(kn_st_result *r)
{
    r->status = KN_ST_SKIPPED;
    snprintf(r->reason, sizeof r->reason,
             "win32-only (ConEmuHk probe); run on the target machine");
    snprintf(r->evidence, sizeof r->evidence, "{\"platform\":\"posix-host\"}");
    return 0;
}
#endif

/* ==================================================== decode.synthetic */

/* External clip discovery: KN_SYNTHETIC_H264 env, then ./synthetic.264,
 * then <exe dir>/synthetic.264. When none is found, the self-test falls back
 * to the clip EMBEDDED at build time (kn_synthetic_clip.h) — hermetic. */
static int kd_file_exists(const char *p)
{
    FILE *f = fopen(p, "rb");
    if (!f) return 0;
    fclose(f);
    return 1;
}

static int kd_find_clip(char *out, size_t outsz)
{
    const char *env = getenv("KN_SYNTHETIC_H264");
    if (env && env[0] && kd_file_exists(env)) {
        snprintf(out, outsz, "%s", env);
        return 0;
    }
    if (kd_file_exists("synthetic.264")) {
        snprintf(out, outsz, "synthetic.264");
        return 0;
    }
#ifdef _WIN32
    {
        char exe[512];
        DWORD n = GetModuleFileNameA(NULL, exe, sizeof exe);
        if (n > 0 && n < sizeof exe) {
            char *slash = strrchr(exe, '\\');
            if (!slash) slash = strrchr(exe, '/');
            if (slash) {
                snprintf(slash + 1, (size_t)(exe + sizeof exe - slash - 1),
                         "synthetic.264");
                if (kd_file_exists(exe)) {
                    snprintf(out, outsz, "%s", exe);
                    return 0;
                }
            }
        }
    }
#else
    {
        char exe[512];
        ssize_t n = readlink("/proc/self/exe", exe, sizeof exe - 1);
        if (n > 0) {
            char *slash;
            exe[n] = '\0';
            slash = strrchr(exe, '/');
            if (slash) {
                snprintf(slash + 1, (size_t)(exe + sizeof exe - slash - 1),
                         "synthetic.264");
                if (kd_file_exists(exe)) {
                    snprintf(out, outsz, "%s", exe);
                    return 0;
                }
            }
        }
    }
#endif
    return -1;
}

typedef struct { long long frames; } kd_count;
static int kd_count_cb(const uint8_t *data, int w, int h, int sy, int suv,
                       int is_nv12, long long idx, void *ud)
{
    kd_count *c = (kd_count *)ud;
    (void)data; (void)w; (void)h; (void)sy; (void)suv; (void)is_nv12; (void)idx;
    c->frames++;
    return 0;
}

static int st_decode_synthetic(kn_st_result *r)
{
    char clip[512];
    kn_decode_stats st;
    kd_count cnt;
    int rc, embedded = 0;

    if (!kn_decode_available()) {
        r->status = KN_ST_SKIPPED;
        snprintf(r->reason, sizeof r->reason,
                 "built without FFmpeg (%s) — rebuild with "
                 "-DKN_FFMPEG_PREFIX=<dev tree>", kn_decode_backend());
        snprintf(r->evidence, sizeof r->evidence, "{\"backend\":\"stub\"}");
        return 0;
    }
    if (kd_find_clip(clip, sizeof clip) != 0) {
        /* hermetic fallback: the clip embedded at build time (§7.9 says
         * "a BUNDLED .264" — the binary carries its own proof) */
        snprintf(clip, sizeof clip, "<embedded %u B>", KN_SYNTH_CLIP_LEN);
        embedded = 1;
    }

    memset(&cnt, 0, sizeof cnt);
    memset(&st, 0, sizeof st);
    if (embedded)
        rc = kn_decode_h264_mem(k_synthetic_clip, KN_SYNTH_CLIP_LEN, 1,
                                kd_count_cb, &cnt, &st);
    else
        rc = kn_decode_h264_file(clip, 1, kd_count_cb, &cnt, &st);

    if (embedded) {
        /* five assertions: rc, exact frame count, no failed frames, callback
         * count == stats count, exact dimensions (the clip is known) */
        r->checks = 5;
        r->failures = (rc == 0 &&
                       st.frames_decoded == KN_SYNTH_CLIP_FRAMES &&
                       st.frames_failed == 0 &&
                       cnt.frames == (long long)st.frames_decoded &&
                       st.width == KN_SYNTH_CLIP_WIDTH &&
                       st.height == KN_SYNTH_CLIP_HEIGHT) ? 0 : 1;
    } else {
        r->checks = 4;
        r->failures = (rc == 0 && st.frames_decoded > 0 &&
                       st.frames_failed == 0 &&
                       cnt.frames == (long long)st.frames_decoded) ? 0 : 1;
    }

    if (r->failures) {
        r->status = KN_ST_FAILED;
        snprintf(r->reason, sizeof r->reason,
                 "decode failed: rc=%d frames=%d (expected %s) failed=%d "
                 "(%s) — decoder vs transport separation is inconclusive",
                 rc, st.frames_decoded,
                 embedded ? "60" : ">0", st.frames_failed,
                 kn_decode_backend());
    } else if (st.fps < 60.0) {
        r->status = KN_ST_DEGRADED;
        snprintf(r->reason, sizeof r->reason,
                 "decoded %d frames but only %.1f fps (320x240 should exceed "
                 "60 fps even on the E5500) — investigate CPU load",
                 st.frames_decoded, st.fps);
    } else {
        r->status = KN_ST_OK;
        snprintf(r->reason, sizeof r->reason,
                 "%d frames %dx%d at %.1f fps, cpu %.0f%% of one core, "
                 "worst frame %lld ms (%s)",
                 st.frames_decoded, st.width, st.height, st.fps,
                 st.cpu_pct_of_core, st.decode_ms_max, kn_decode_backend());
    }
    snprintf(r->evidence, sizeof r->evidence,
             "{\"backend\":\"%s\",\"clip\":\"%s\",\"rc\":%d,\"frames\":%d,"
             "\"failed\":%d,\"cb_frames\":%lld,\"width\":%d,\"height\":%d,"
             "\"fps\":%.1f,\"cpu_pct_of_core\":%.1f,\"decode_ms_max\":%lld,"
             "\"wall_ms\":%lld}",
             kn_decode_backend(), clip, rc, st.frames_decoded, st.frames_failed,
             cnt.frames, st.width, st.height, st.fps, st.cpu_pct_of_core,
             st.decode_ms_max, st.wall_ms);
    return 0;
}

