/* ============================================================= d3d probes */

/* The real work lives in kn_d3d.c (all D3D9 types stay there — this file
 * remains platform-neutral). Evidence base: G0.2-T4v4-RESULTS.md; the
 * expectations encoded below are the MEASURED target facts (§2.1-§2.5), so
 * a driver update that changes the D7 rungs shows up here first. */

static const char *st_d3dfmt_name(unsigned fmt, char *buf, size_t bufsz)
{
    switch (fmt) {
    case 21u: return "A8R8G8B8";       /* D3DFMT enum values (verified) */
    case 22u: return "X8R8G8B8";
    case 23u: return "R5G6B5";
    default:
        snprintf(buf, bufsz, "0x%08x", fmt);   /* unsigned: bounded by type */
        return buf;
    }
}

static void st_d3d_skip_posix(kn_st_result *r)
{
    r->status = KN_ST_SKIPPED;
    snprintf(r->reason, sizeof r->reason,
             "win32-only (D3D9); run on the target machine");
    snprintf(r->evidence, sizeof r->evidence, "{\"platform\":\"posix-host\"}");
}

static int st_d3d_formats(kn_st_result *r)
{
    kn_d3d_formats f;
    st_tally t;
    char extra[768], fbuf[16];
    const char *bbname;
    int rung1, rung2, rung3, linear, dev_ok;

    if (!kn_d3d_available()) { st_d3d_skip_posix(r); return 0; }
    memset(&t, 0, sizeof t);
    (void)kn_d3d_probe_formats(&f);

    STV(t, f.d3d_created, "Direct3DCreate9");
    STV(t, f.adapter_count >= 1, "adapter count >= 1");
    STV(t, f.mode_w > 0 && f.mode_h > 0 && f.mode_hz > 0, "display mode read");
    STV(t, f.modes_60hz_at_res >= 1, "60 Hz mode at current resolution (R9)");
    STV(t, f.d3d_created && f.hr_dev_hwvp >= 0,
        "HAL + HARDWARE_VERTEXPROCESSING device");
    STV(t, f.fmt_nv12 == 1, "NV12 surface format (D7 rung 1)");
    STV(t, f.conv_nv12_to_mode == 1, "NV12 -> backbuffer conversion");
    STV(t, f.srf_min_linear && f.srf_mag_linear, "LINEAR stretch filter caps");
    STV(t, f.conv_yuy2_to_mode == 1, "YUY2 -> backbuffer conversion (rung 2)");
    STV(t, f.conv_x8_to_mode == 1, "X8R8G8B8 -> backbuffer (rung 3)");

    dev_ok = (f.hr_dev_hwvp >= 0);
    rung1 = (f.fmt_nv12 == 1 && f.conv_nv12_to_mode == 1);
    rung2 = (f.fmt_yuy2 == 1 && f.conv_yuy2_to_mode == 1);
    rung3 = (f.fmt_x8r8g8b8 == 1 && f.conv_x8_to_mode == 1);
    linear = (f.srf_min_linear && f.srf_mag_linear);
    bbname = st_d3dfmt_name(f.mode_fmt, fbuf, sizeof fbuf);

    if (!f.d3d_created || !dev_ok || f.mode_w == 0 ||
        (!rung1 && !rung2 && !rung3))
        r->status = KN_ST_FAILED;
    else if (!rung1 || !linear || f.modes_60hz_at_res < 1)
        r->status = KN_ST_DEGRADED;
    else
        r->status = KN_ST_OK;

    if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "D7 rung 1 available: NV12->%s conversion ok, LINEAR caps, "
                 "HAL+HWVP device ok; %ux%u@%u Hz; PCI %04x:%04x",
                 bbname, f.mode_w % 100000u, f.mode_h % 100000u,
                 f.mode_hz % 10000u, f.vendor_id % 0x10000u,
                 f.device_id % 0x10000u);
    else if (r->status == KN_ST_DEGRADED)
        snprintf(r->reason, sizeof r->reason,
                 "USABLE but off-nominal: rung1 NV12 %s, LINEAR %s, 60Hz %s "
                 "(%d/%d checks failed, first: %.64s)",
                 rung1 ? "ok" : "MISSING", linear ? "ok" : "MISSING",
                 f.modes_60hz_at_res >= 1 ? "ok" : "MISSING",
                 t.failures, t.checks, t.first_fail);
    else
        snprintf(r->reason, sizeof r->reason,
                 "D3D9 unusable: d3d=%d hwvp=0x%08lx mode=%ux%u "
                 "(%d/%d checks failed, first: %.64s)",
                 f.d3d_created, (unsigned long)f.hr_dev_hwvp,
                 f.mode_w % 100000u, f.mode_h % 100000u,
                 t.failures, t.checks, t.first_fail);

    snprintf(extra, sizeof extra,
             "\"adapter\":\"%04x:%04x\",\"driver\":\"0x%016llx\","
             "\"desc\":\"%.40s\",\"mode\":\"%ux%u@%u\",\"bb\":\"%s\","
             "\"modes\":%d,\"hz60_at_res\":%d,\"hwvp\":\"0x%08lx\","
             "\"swvp\":\"0x%08lx\",\"fmt\":{\"nv12\":%d,\"yuy2\":%d,"
             "\"uyvy\":%d,\"x8\":%d,\"a8\":%d,\"r5g6\":%d,\"x1r5\":%d},"
             "\"conv\":{\"nv12\":%d,\"yuy2\":%d,\"x8\":%d,\"to_nv12\":%d},"
             "\"srf_caps\":\"0x%08llx\",\"linear\":%d,\"point\":%d,"
             "\"imm\":%d,\"one\":%d",
             f.vendor_id % 0x10000u, f.device_id % 0x10000u,
             f.driver_version, f.description,
             f.mode_w % 100000u, f.mode_h % 100000u, f.mode_hz % 10000u,
             bbname, f.mode_count, f.modes_60hz_at_res,
             (unsigned long)f.hr_dev_hwvp, (unsigned long)f.hr_dev_swvp,
             f.fmt_nv12, f.fmt_yuy2, f.fmt_uyvy, f.fmt_x8r8g8b8,
             f.fmt_a8r8g8b8, f.fmt_r5g6b5, f.fmt_x1r5g5b5,
             f.conv_nv12_to_mode, f.conv_yuy2_to_mode, f.conv_x8_to_mode,
             f.conv_mode_to_nv12,
             f.srf_caps, f.srf_mag_linear || f.srf_min_linear,
             f.srf_mag_point || f.srf_min_point,
             f.interval_immediate, f.interval_one);
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\",%s}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}

static int st_d3d_present(kn_st_result *r)
{
    kn_d3d_present p;
    st_tally t;
    char extra[768];
    int prc;

    if (!kn_d3d_available()) { st_d3d_skip_posix(r); return 0; }
    memset(&t, 0, sizeof t);
    prc = kn_d3d_probe_present(&p);

    /* R25 milestone 0: the fill of a locked DEFAULT NV12 surface is the one
     * operation G0.2 never exercised (SYSTEMMEM fill AVs the driver — the
     * VEH guard here catches the same shape on DEFAULT and latches a
     * permanent degrade per D7). */
    STV(t, p.seh_code == 0, "no exception writing locked DEFAULT NV12 (R25)");
    STV(t, p.window_created, "fullscreen probe window");
    if (p.window_created) {
        STV(t, p.hr_device >= 0, "HAL+HWVP device");
        if (p.hr_device >= 0) {
            STV(t, p.hr_conv >= 0, "NV12->backbuffer conversion check");
            STV(t, p.hr_surface >= 0, "NV12 DEFAULT surface created");
            if (p.hr_surface >= 0) {
                STV(t, p.hr_lock >= 0 && p.pitch >= (int)p.video_w,
                    "LockRect pitch honoured");
                STV(t, p.fill_mismatches == 0, "fill read-back verified");
                STV(t, p.hr_stretch >= 0, "StretchRect(LINEAR) -> backbuffer");
                STV(t, p.hr_present >= 0, "Present S_OK");
                STV(t, p.iterations_done == p.iterations,
                    "every iteration completed");
                if (p.iterations_done == p.iterations)
                    STV(t, p.hr_tcl_after >= 0, "cooperative level after loop");
            }
        }
    }

    if (p.seh_code != 0 || p.permanently_degraded)
        r->status = KN_ST_FAILED;
    else if (t.failures == 0 && p.ok && prc == 0)
        r->status = (p.present_mean_ms > 16.7) ? KN_ST_DEGRADED : KN_ST_OK;
    else
        r->status = KN_ST_FAILED;

    if (p.seh_code != 0)
        snprintf(r->reason, sizeof r->reason,
                 "EXCEPTION 0x%08lx writing locked DEFAULT NV12 at 0x%016llx "
                 "after %d/%d iters — R25 confirmed; D7 permanent degrade, "
                 "video path must use the GDI rung",
                 p.seh_code, p.seh_write_addr,
                 p.iterations_done, p.iterations);
    else if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "R25 milestone 0 OK: %ux%u NV12 DEFAULT fill verified, "
                 "StretchRect+Present x%d, present mean %.2f ms max %.2f ms, "
                 "fill mean %.2f ms, pitch %d",
                 p.video_w % 100000u, p.video_h % 100000u,
                 p.iterations_done, p.present_mean_ms, p.present_max_ms,
                 p.fill_mean_ms, p.pitch);
    else if (r->status == KN_ST_DEGRADED)
        snprintf(r->reason, sizeof r->reason,
                 "milestone 0 works but present mean %.2f ms exceeds the "
                 "16.7 ms/60Hz budget — G1 pacing must account for it",
                 p.present_mean_ms);
    else
        snprintf(r->reason, sizeof r->reason,
                 "milestone 0 incomplete: %d/%d iters (%d/%d checks failed, "
                 "first: %.64s)",
                 p.iterations_done, p.iterations,
                 t.failures, t.checks, t.first_fail);

    snprintf(extra, sizeof extra,
             "\"ok\":%s,\"iters\":\"%d/%d\",\"pitch\":%d,"
             "\"video\":\"%ux%u\",\"screen\":\"%ux%u\","
             "\"dest\":\"%d,%d,%d,%d\",\"fill_ms_mean\":%.2f,"
             "\"fill_ms_max\":%.2f,\"present_ms_mean\":%.2f,"
             "\"present_ms_max\":%.2f,\"filter\":\"linear\","
             "\"mismatches\":%d,\"bytes_per_fill\":%llu,"
             "\"hrs\":{\"dev\":\"0x%08lx\",\"conv\":\"0x%08lx\","
             "\"surf\":\"0x%08lx\",\"lock\":\"0x%08lx\","
             "\"stretch\":\"0x%08lx\",\"present\":\"0x%08lx\","
             "\"tcl\":\"0x%08lx\"},\"seh\":\"0x%08lx\","
             "\"seh_addr\":\"0x%016llx\",\"degraded_latch\":%s",
             p.ok ? "true" : "false", p.iterations_done, p.iterations,
             p.pitch, p.video_w % 100000u, p.video_h % 100000u,
             p.screen_w % 100000u, p.screen_h % 100000u,
             p.dest_x0, p.dest_y0, p.dest_x1, p.dest_y1,
             p.fill_mean_ms, p.fill_max_ms, p.present_mean_ms,
             p.present_max_ms, p.fill_mismatches, p.fill_bytes_per_iter,
             (unsigned long)p.hr_device, (unsigned long)p.hr_conv,
             (unsigned long)p.hr_surface, (unsigned long)p.hr_lock,
             (unsigned long)p.hr_stretch, (unsigned long)p.hr_present,
             (unsigned long)p.hr_tcl_after, p.seh_code, p.seh_write_addr,
             p.permanently_degraded ? "true" : "false");
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\",%s}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}

static int st_gs_parse(kn_st_result *r)
{
    st_tally t;
    char extra[640];
    char capnote[320];   /* worst case: 107 literal + 128 path + 8x6 digits
                          * + NUL = 284 (T10 round 6: GCC 16 proves the
                          * directive bounds — 256 was too tight, R28) */
    int i;
    unsigned cap_lines = 0, cap_bad = 0, cap_rtp_ok = 0, cap_rtp_err = 0;
    unsigned cap_gs = 0, cap_sof = 0, cap_eof = 0, cap_fec = 0;
    const char *cap_path = NULL;

    memset(&t, 0, sizeof t);

    /* ---- the KAT battery (portable: synthetic vectors from the spec) ---- */
    for (i = 0; i < K_KAT_RTP_N; ++i) {
        const kn_gs_kat_rtp *v = &k_kat_rtp[i];
        kn_gs_rtp h;
        int rc = kn_gs_rtp_parse(v->pkt, v->len, &h);
        STV(t, (v->rc != KN_GS_OK)
               ? (rc == v->rc)
               : (rc == KN_GS_OK && h.pt == v->pt && h.seq == v->seq &&
                  h.timestamp == (uint32_t)v->ts &&
                  h.ssrc == (uint32_t)v->ssrc &&
                  h.payload_off == v->payload_off &&
                  h.payload_len == v->payload_len &&
                  h.has_padding == v->has_padding && h.has_gs == v->has_gs &&
                  (v->has_gs == 0 || h.gs_off == v->gs_off)),
            v->name);
    }
    for (i = 0; i < K_KAT_VIDEO_N; ++i) {
        const kn_gs_kat_video *v = &k_kat_video[i];
        kn_gs_video g;
        STV(t, kn_gs_video_parse(v->ext, &g) == KN_GS_OK &&
               g.stream_packet_index == v->spi &&
               g.frame_index == v->frame_index && g.flags == v->flags &&
               g.fec_current_block == v->cur && g.fec_last_block == v->last &&
               g.fec_percentage == v->pct && g.fec_index == v->fidx &&
               g.fec_source_packets == v->fsrc && g.is_fec == v->is_fec &&
               g.is_start_of_frame == v->sof &&
               g.is_end_of_frame == v->eof &&
               g.flags_valid == v->flags_valid, v->name);
    }
    for (i = 0; i < K_KAT_PAYLOAD_N; ++i) {
        const kn_gs_kat_payload *v = &k_kat_payload[i];
        size_t off = 0;
        int rc = kn_gs_picture_payload(v->codec, v->pay, v->len, &off);
        STV(t, rc == v->rc && (v->rc != KN_GS_OK || off == v->off), v->name);
    }
    for (i = 0; i < K_KAT_KEY_N; ++i) {
        const kn_gs_kat_key *v = &k_kat_key[i];
        STV(t, kn_gs_is_keyframe(v->codec, v->b, v->len, v->hint) ==
               v->keyframe, v->name);
    }
    for (i = 0; i < K_KAT_AUD_N; ++i) {
        const kn_gs_kat_aud *v = &k_kat_aud[i];
        STV(t, kn_gs_strip_trailing_aud(v->codec, v->b, v->len) == v->newlen,
            v->name);
    }
    for (i = 0; i < K_KAT_FEC_N; ++i) {
        const kn_gs_kat_fec *v = &k_kat_fec[i];
        kn_gs_fec_layout lay;
        int rc = kn_gs_fec_layout_parse(v->ext, &lay);
        STV(t, (v->rc != KN_GS_OK)
               ? (rc == v->rc)
               : (rc == KN_GS_OK && lay.frame_index == v->frame_index &&
                  lay.block_index == v->block &&
                  lay.last_block_index == v->last_block &&
                  lay.shard_index == v->shard && lay.data_shards == v->data &&
                  lay.parity_shards == v->parity),
            v->name);
    }
    for (i = 0; i < K_KAT_CONT_N; ++i) {
        STV(t, kn_gs_index_continuous(k_kat_cont[i][0], k_kat_cont[i][1]) ==
               (int)k_kat_cont[i][2], "continuity");
    }
    for (i = 0; i < K_KAT_HEX_N; ++i) {
        const kn_gs_kat_hex *v = &k_kat_hex[i];
        kn_gs_dump_rec rec;
        unsigned char pay[2048];
        size_t got = 0;
        int rc = kn_gs_hexdump_parse_line(v->line, &rec, pay, sizeof pay,
                                          &got);
        STV(t, (v->rc != KN_GS_OK)
               ? (rc == v->rc)
               : (rc == KN_GS_OK && rec.mono_us == v->mono_us &&
                  rec.meta == v->meta && rec.flags == v->flags &&
                  rec.len == v->len && got == v->len &&
                  (v->len == 0 || memcmp(pay, v->payload, v->len) == 0)),
            v->name);
    }

    /* ---- optional REAL capture (kn_ring_dump hexdump text). Discovery:
     * KN_GS_CAPTURE env, then ./gs_capture.hex. Stage 2 records these from
     * the live socket; until then the KAT battery is the whole test and the
     * reason says so (name your unknowns). ---- */
    {
        const char *env = getenv("KN_GS_CAPTURE");
        FILE *f = NULL;
        if (env && env[0]) {
            f = fopen(env, "rb");
            if (f) cap_path = env;
        }
        if (!f) {
            f = fopen("gs_capture.hex", "rb");
            if (f) cap_path = "gs_capture.hex";
        }
        if (f) {
            static char linebuf[16384];
            unsigned char pay[4096];
            while (cap_lines < 100000u && fgets(linebuf, (int)sizeof linebuf,
                                                f)) {
                kn_gs_dump_rec rec;
                size_t got = 0;
                int rc;
                size_t llen = strcspn(linebuf, "\r\n");
                if (linebuf[llen] != '\0' && llen + 1u == sizeof linebuf) {
                    /* line longer than the buffer: skip to its end */
                    int c;
                    cap_bad++;
                    while ((c = fgetc(f)) != EOF && c != '\n') { }
                    continue;
                }
                cap_lines++;
                rc = kn_gs_hexdump_parse_line(linebuf, &rec, pay, sizeof pay,
                                              &got);
                if (rc != KN_GS_OK) { cap_bad++; continue; }
                if (got >= KN_GS_FIXED_HEADER_LEN) {
                    kn_gs_rtp h;
                    if (kn_gs_rtp_parse(pay, got, &h) == KN_GS_OK) {
                        cap_rtp_ok++;
                        if (h.has_gs) {
                            kn_gs_video g;
                            cap_gs++;
                            if (kn_gs_video_parse(pay + h.gs_off, &g)
                                == KN_GS_OK) {
                                cap_sof += (unsigned)g.is_start_of_frame;
                                cap_eof += (unsigned)g.is_end_of_frame;
                                cap_fec += (unsigned)g.is_fec;
                            }
                        }
                    } else {
                        cap_rtp_err++;
                    }
                }
            }
            fclose(f);
            STV(t, cap_bad == 0, "capture: every line well-formed");
            snprintf(capnote, sizeof capnote,
                     "\"capture\":\"%.128s\",\"cap_lines\":%u,\"cap_bad\":%u,"
                     "\"cap_rtp_ok\":%u,\"cap_rtp_err\":%u,\"cap_gs\":%u,"
                     "\"cap_sof\":%u,\"cap_eof\":%u,\"cap_fec\":%u",
                     cap_path ? cap_path : "", cap_lines % 1000000u,
                     cap_bad % 1000000u, cap_rtp_ok % 1000000u,
                     cap_rtp_err % 1000000u, cap_gs % 1000000u,
                     cap_sof % 1000000u, cap_eof % 1000000u,
                     cap_fec % 1000000u);
        } else {
            snprintf(capnote, sizeof capnote,
                     "\"capture\":\"none (stage 2 records real dumps)\"");
        }
    }

    if (t.failures == 0) {
        r->status = KN_ST_OK;
        snprintf(r->reason, sizeof r->reason,
                 "all %d known-answer checks passed%s%.96s",
                 t.checks, cap_path ? "; capture parsed: " : "",
                 cap_path ? cap_path : "");
    } else {
        r->status = KN_ST_FAILED;
        snprintf(r->reason, sizeof r->reason,
                 "%d/%d GS parse checks FAILED (first: %.64s) — shipped "
                 "binary disagrees with the nvst.rs reference vectors",
                 t.failures, t.checks, t.first_fail);
    }
    snprintf(extra, sizeof extra,
             "\"vectors\":\"kn_gs_kat_vectors.h (tools/gs_reference.py)\",%s",
             capnote);
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\",%s}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}
/* ==================================================== phase C: net probes
 * REAL network measurements from the target machine (§7.9): the endpoints
 * come from the research index (BOOTSTRAP §5: login.nvidia.com for the
 * OAuth device grant, prod.cloudmatchbeta.nvidiagrid.net for CloudMatch,
 * s1.stun.gamestream.nvidia.com / stun.l.google.com for STUN) plus one
 * non-NVIDIA baseline per layer, so "NVIDIA unreachable" is separable from
 * "this machine has no network". TLS runs on schannel — the SAME stack the
 * stage-2 client will use — with verification ALWAYS ON (working
 * agreement): a failed handshake is the measurement, reported with its
 * SECURITY_STATUS, never bypassed. */

#define K_NET_NVIDIA_N 2
static const char *const k_net_nvidia[K_NET_NVIDIA_N] = {
    "login.nvidia.com",
    "prod.cloudmatchbeta.nvidiagrid.net"
};
#define K_NET_DNS_BASELINE "stun.l.google.com"
#define K_NET_TLS_BASELINE "www.cloudflare.com"

static void st_net_skip_posix(kn_st_result *r, const char *what)
{
    r->status = KN_ST_SKIPPED;
    snprintf(r->reason, sizeof r->reason,
             "win32-only (%s); run on the target machine", what);
    snprintf(r->evidence, sizeof r->evidence, "{\"platform\":\"posix-host\"}");
}

static int st_net_dns(kn_st_result *r)
{
    kn_net_dns d[K_NET_NVIDIA_N + 1];
    st_tally t;
    char extra[704];
    int i, base_ok;

    if (!kn_net_available()) { st_net_skip_posix(r, "winsock DNS"); return 0; }
    memset(&t, 0, sizeof t);
    for (i = 0; i < K_NET_NVIDIA_N; ++i)
        (void)kn_net_dns_lookup(k_net_nvidia[i], &d[i]);
    (void)kn_net_dns_lookup(K_NET_DNS_BASELINE, &d[K_NET_NVIDIA_N]);
    base_ok = (d[K_NET_NVIDIA_N].rc == 0);

    STV(t, base_ok, "baseline DNS resolves (local resolver works)");
    for (i = 0; i < K_NET_NVIDIA_N; ++i) {
        char nm[80];
        snprintf(nm, sizeof nm, "%.48s resolves", k_net_nvidia[i]);
        STV(t, d[i].rc == 0 && (d[i].a_count + d[i].aaaa_count) > 0, nm);
    }

    if (t.failures == 0)
        r->status = KN_ST_OK;
    else if (!base_ok)
        r->status = KN_ST_FAILED;      /* no resolution at all */
    else
        r->status = KN_ST_FAILED;      /* NVIDIA unreachable = stage-2 blocker */

    if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "%d/%d hosts resolve; login.nvidia.com -> %.15s (A=%u, "
                 "AAAA=%u, %ld ms)", K_NET_NVIDIA_N + 1,
                 K_NET_NVIDIA_N + 1, d[0].first_v4, d[0].a_count,
                 d[0].aaaa_count, d[0].ms);
    else if (!base_ok)
        snprintf(r->reason, sizeof r->reason,
                 "NO name resolution at all (baseline failed, gai %d wsa %d) "
                 "— check network/DNS, not the endpoints",
                 d[K_NET_NVIDIA_N].gai_error, d[K_NET_NVIDIA_N].wsa_error);
    else
        snprintf(r->reason, sizeof r->reason,
                 "baseline resolves but an NVIDIA endpoint does NOT "
                 "(%.30s rc %d gai %d) — stage-2 blocker, analyse before "
                 "proceeding", d[0].rc == 0 ? k_net_nvidia[1]
                 : k_net_nvidia[0],
                 d[0].rc != 0 ? d[0].rc : d[1].rc,
                 d[0].rc != 0 ? d[0].gai_error : d[1].gai_error);

    {
        char per[K_NET_NVIDIA_N + 1][192];
        size_t off = 0;
        extra[0] = '\0';
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            snprintf(per[i], sizeof per[i],
                     "%s{\"host\":\"%.40s\",\"rc\":%d,\"a\":%u,\"aaaa\":%u,"
                     "\"v4\":\"%.15s\",\"ms\":%ld}",
                     i ? "," : "",
                     i < K_NET_NVIDIA_N ? k_net_nvidia[i] : K_NET_DNS_BASELINE,
                     d[i].rc, d[i].a_count % 1000u, d[i].aaaa_count % 1000u,
                     d[i].first_v4, d[i].ms);
        }
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            size_t n = strlen(per[i]);
            if (off + n + 1 < sizeof extra) {
                memcpy(extra + off, per[i], n);
                off += n;
                extra[off] = '\0';
            }
        }
    }
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\","
             "\"hosts\":[%s]}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}

static int st_net_tcp443(kn_st_result *r)
{
    kn_net_tcp d[K_NET_NVIDIA_N + 1];
    st_tally t;
    char extra[704];
    int i, base_ok;

    if (!kn_net_available()) { st_net_skip_posix(r, "winsock TCP"); return 0; }
    memset(&t, 0, sizeof t);
    for (i = 0; i < K_NET_NVIDIA_N; ++i)
        (void)kn_net_tcp_connect443(k_net_nvidia[i], &d[i]);
    (void)kn_net_tcp_connect443(K_NET_TLS_BASELINE, &d[K_NET_NVIDIA_N]);
    base_ok = (d[K_NET_NVIDIA_N].rc == 0);

    STV(t, base_ok, "baseline TCP/443 connects (egress open)");
    for (i = 0; i < K_NET_NVIDIA_N; ++i) {
        char nm[80];
        snprintf(nm, sizeof nm, "%.48s:443 connects", k_net_nvidia[i]);
        STV(t, d[i].rc == 0, nm);
    }

    if (t.failures == 0)
        r->status = KN_ST_OK;
    else
        r->status = KN_ST_FAILED;

    if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "TCP/443 open to %d/%d NVIDIA endpoints + baseline "
                 "(login %.15s in %ld ms)", K_NET_NVIDIA_N,
                 K_NET_NVIDIA_N, d[0].peer_ip, d[0].ms);
    else if (!base_ok)
        snprintf(r->reason, sizeof r->reason,
                 "baseline TCP/443 FAILED (rc %d wsa %d) — no outbound 443 "
                 "(firewall/proxy?), endpoints not judgeable",
                 d[K_NET_NVIDIA_N].rc, d[K_NET_NVIDIA_N].wsa_error);
    else
        snprintf(r->reason, sizeof r->reason,
                 "egress OK but an NVIDIA endpoint refuses TCP/443 "
                 "(rc %d wsa %d) — stage-2 blocker, analyse",
                 d[0].rc != 0 ? d[0].rc : d[1].rc,
                 d[0].rc != 0 ? d[0].wsa_error : d[1].wsa_error);

    {
        char per[K_NET_NVIDIA_N + 1][192];
        size_t off = 0;
        extra[0] = '\0';
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            snprintf(per[i], sizeof per[i],
                     "%s{\"host\":\"%.40s\",\"rc\":%d,\"wsa\":%d,"
                     "\"peer\":\"%.15s\",\"ms\":%ld}",
                     i ? "," : "",
                     i < K_NET_NVIDIA_N ? k_net_nvidia[i] : K_NET_TLS_BASELINE,
                     d[i].rc, d[i].wsa_error, d[i].peer_ip, d[i].ms);
        }
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            size_t n = strlen(per[i]);
            if (off + n + 1 < sizeof extra) {
                memcpy(extra + off, per[i], n);
                off += n;
                extra[off] = '\0';
            }
        }
    }
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\","
             "\"hosts\":[%s]}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}

static int st_net_tls(kn_st_result *r)
{
    kn_net_tls d[K_NET_NVIDIA_N + 1];
    st_tally t;
    char extra[832];
    int i, base_ok, old_proto = 0;

    if (!kn_net_available()) { st_net_skip_posix(r, "schannel TLS"); return 0; }
    memset(&t, 0, sizeof t);
    for (i = 0; i < K_NET_NVIDIA_N; ++i)
        (void)kn_net_tls_probe(k_net_nvidia[i], &d[i]);
    (void)kn_net_tls_probe(K_NET_TLS_BASELINE, &d[K_NET_NVIDIA_N]);
    base_ok = (d[K_NET_NVIDIA_N].rc == 0);

    STV(t, base_ok, "baseline TLS handshake verifies (schannel works)");
    for (i = 0; i < K_NET_NVIDIA_N; ++i) {
        char nm[80];
        snprintf(nm, sizeof nm, "%.40s TLS handshake VERIFIES", k_net_nvidia[i]);
        STV(t, d[i].rc == 0, nm);
    }
    for (i = 0; i <= K_NET_NVIDIA_N; ++i)
        if (d[i].rc == 0 && (d[i].protocol & 0x00000A00ul) == 0)
            old_proto = 1;      /* below TLS1.2 (0x800) / TLS1.3 (0x2000) */

    if (!base_ok || t.failures > 0)
        r->status = KN_ST_FAILED;
    else if (old_proto)
        r->status = KN_ST_DEGRADED;
    else
        r->status = KN_ST_OK;

    if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "schannel TLS verified on all %d hosts: login %.5s "
                 "cipher %u-bit, leaf '%.40s'", K_NET_NVIDIA_N + 1,
                 d[0].protocol_name, d[0].cipher_bits % 100000u,
                 d[0].subject);
    else if (r->status == KN_ST_DEGRADED)
        snprintf(r->reason, sizeof r->reason,
                 "TLS verifies but a host negotiated BELOW TLS 1.2 (%.5s) — "
                 "workable today, revisit before stage-2 crypto decisions",
                 d[0].protocol_name);
    else if (!base_ok)
        snprintf(r->reason, sizeof r->reason,
                 "baseline TLS FAILED (sec 0x%08lx) — schannel/egress issue, "
                 "NVIDIA endpoints not judgeable",
                 (unsigned long)d[K_NET_NVIDIA_N].sec_status);
    else
        snprintf(r->reason, sizeof r->reason,
                 "TLS to an NVIDIA endpoint FAILED (login sec 0x%08lx, "
                 "cloudmatch sec 0x%08lx) while baseline works — Win7 TLS "
                 "reality: analyse version/cert store (tls.chain) BEFORE "
                 "stage 2", (unsigned long)d[0].sec_status,
                 (unsigned long)d[1].sec_status);

    {
        char per[K_NET_NVIDIA_N + 1][256];
        size_t off = 0;
        extra[0] = '\0';
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            snprintf(per[i], sizeof per[i],
                     "%s{\"host\":\"%.40s\",\"rc\":%d,\"sec\":\"0x%08lx\","
                     "\"proto\":\"%.8s\",\"cipher_bits\":%u,"
                     "\"leaf\":\"%.32s\"}",
                     i ? "," : "",
                     i < K_NET_NVIDIA_N ? k_net_nvidia[i] : K_NET_TLS_BASELINE,
                     d[i].rc, (unsigned long)d[i].sec_status,
                     d[i].protocol_name, d[i].cipher_bits % 100000u,
                     d[i].subject);
        }
        for (i = 0; i <= K_NET_NVIDIA_N; ++i) {
            size_t n = strlen(per[i]);
            if (off + n + 1 < sizeof extra) {
                memcpy(extra + off, per[i], n);
                off += n;
                extra[off] = '\0';
            }
        }
    }
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.96s\","
             "\"hosts\":[%s]}",
             t.checks, t.failures, t.first_fail, extra);
    return 0;
}

static int st_tls_chain(kn_st_result *r)
{
    kn_net_chain c;
    st_tally t;
    char extra[768];

    if (!kn_net_available()) { st_net_skip_posix(r, "schannel chain"); return 0; }
    memset(&t, 0, sizeof t);
    (void)kn_net_chain_dump("login.nvidia.com", &c);

    STV(t, c.rc >= 0 && c.sec_status == 0, "handshake for chain dump ok");
    STV(t, c.rc == 0 && c.depth >= 1, "OS built a chain (depth >= 1)");
    STV(t, c.chain_trust == 0, "chain TrustStatus clean (0x0)");
    STV(t, c.policy_error == 0, "SSL policy verdict clean (0x0)");

    if (c.rc < 0 || c.sec_status != 0)
        r->status = KN_ST_FAILED;
    else if (c.depth < 1)
        r->status = KN_ST_FAILED;
    else if (t.failures > 0)
        r->status = KN_ST_DEGRADED;    /* built, but trust flags set — the
                                          §7.9 "stale Win7 store" finding */
    else
        r->status = KN_ST_OK;

    if (r->status == KN_ST_OK)
        snprintf(r->reason, sizeof r->reason,
                 "login.nvidia.com chain clean: depth %d, root '%.44s', "
                 "trust 0x%08lx, policy 0x%08lx", c.depth,
                 c.depth > 0 ? c.elem[c.depth - 1].subject : "",
                 c.chain_trust, c.policy_error);
    else if (r->status == KN_ST_DEGRADED)
        snprintf(r->reason, sizeof r->reason,
                 "chain BUILT but flagged: trust 0x%08lx policy 0x%08lx "
                 "(depth %d) — stale Win7 store / missing root? Diagnosis "
                 "only; verification is never bypassed",
                 c.chain_trust, c.policy_error, c.depth);
    else
        snprintf(r->reason, sizeof r->reason,
                 "chain dump failed: rc %d sec 0x%08lx depth %d — the TLS "
                 "handshake itself failed; see net.tls for the verdict",
                 c.rc, (unsigned long)c.sec_status, c.depth);

    {
        char per[KN_NET_CHAIN_MAX][160];
        size_t off = 0;
        int i;
        extra[0] = '\0';
        for (i = 0; i < c.depth && i < KN_NET_CHAIN_MAX; ++i) {
            snprintf(per[i], sizeof per[i],
                     "%s{\"i\":%d,\"subject\":\"%.28s\",\"issuer\":\"%.28s\","
                     "\"not_after\":\"%.11s\",\"trust\":\"0x%08lx\"}",
                     i ? "," : "", i, c.elem[i].subject, c.elem[i].issuer,
                     c.elem[i].not_after, c.elem[i].trust_error);
        }
        for (i = 0; i < c.depth && i < KN_NET_CHAIN_MAX; ++i) {
            size_t n = strlen(per[i]);
            if (off + n + 1 < sizeof extra) {
                memcpy(extra + off, per[i], n);
                off += n;
                extra[off] = '\0';
            }
        }
    }
    r->checks = t.checks;
    r->failures = t.failures;
    snprintf(r->evidence, sizeof r->evidence,
             "{\"checks\":%d,\"failures\":%d,\"first_failure\":\"%.64s\","
             "\"depth\":%d,\"trust\":\"0x%08lx\",\"policy\":\"0x%08lx\","
             "\"policy_at\":[%ld,%ld],\"chain\":[%s]}",
             t.checks, t.failures, t.first_fail, c.depth, c.chain_trust,
             c.policy_error, c.policy_chain_index, c.policy_element_index,
             extra);
    return 0;
}

/* ================================================================ registry */

typedef int (*kn_st_fn)(kn_st_result *r);

static const struct {
    const char *name;
    kn_st_fn    fn;
} k_registry[] = {
    /* phase A — offline, host-testable */
    { "fec.vectors",      st_fec_vectors },
    { "srtp.vectors",     st_srtp_vectors },
    /* phase B — offline/Win32, no network (gs.parse is portable: KAT
     * vectors everywhere, optional real capture on the target) */
    { "clock.resolution", st_clock_resolution },
    { "console.host",     st_console_host },
    { "d3d.formats",      st_d3d_formats },
    { "d3d.present",      st_d3d_present },
    { "decode.synthetic", st_decode_synthetic },
    { "gs.parse",         st_gs_parse },
    /* phase C — network, target machine only (REAL measurements; skipped
     * honestly on posix hosts). Implemented (round XV): no stubs remain. */
    { "net.dns",          st_net_dns },
    { "net.tcp443",       st_net_tcp443 },
    { "net.tls",          st_net_tls },
    { "tls.chain",        st_tls_chain },
};

#define K_REGISTRY_N ((int)(sizeof k_registry / sizeof k_registry[0]))

const char *kn_selftest_status_name(int status)
{
    switch (status) {
    case KN_ST_OK:       return "ok";
    case KN_ST_DEGRADED: return "degraded";
    case KN_ST_FAILED:   return "failed";
    case KN_ST_SKIPPED:  return "skipped";
    default:             return "unknown";
    }
}

int kn_selftest_count(void) { return K_REGISTRY_N; }

int kn_selftest_is_gated(const char *name)
{
    if (!name) return 1;
    return strcmp(name, "net.tls") != 0 && strcmp(name, "tls.chain") != 0;
}

const char *kn_selftest_name(int idx)
{
    return (idx >= 0 && idx < K_REGISTRY_N) ? k_registry[idx].name : NULL;
}

int kn_selftest_run(const char *name, kn_st_result *r)
{
    int i;
    long long t0;
    if (!name || !r) return -1;
    for (i = 0; i < K_REGISTRY_N; ++i) {
        if (strcmp(k_registry[i].name, name) != 0) continue;
        memset(r, 0, sizeof *r);
        snprintf(r->name, sizeof r->name, "%s", name);
        t0 = st_mono_ms();
        (void)k_registry[i].fn(r);
        r->ms = st_mono_ms() - t0;
        return 0;
    }
    return -1;
}

int kn_selftest_run_all(kn_st_result *results, int max)
{
    int i, n = 0;
    if (!results || max <= 0) return 0;
    for (i = 0; i < K_REGISTRY_N && n < max; ++i)
        if (kn_selftest_run(k_registry[i].name, &results[n]) == 0) ++n;
    return n;
}

/* ------------------------------------------------------------- JSON render */

/* Bounded cursor-append (knlog.c pattern). */
#define ST_APP(buf, bufsz, o, trunc, ...)                                \
    do {                                                                  \
        if ((o) < (bufsz)) {                                              \
            int n_ = snprintf((buf) + (o), (bufsz) - (o), __VA_ARGS__);   \
            if (n_ < 0) n_ = 0;                                           \
            if ((size_t)n_ >= (bufsz) - (o)) { (o) = (bufsz) - 1; *(trunc) = 1; } \
            else { (o) += (size_t)n_; }                                   \
        }                                                                 \
    } while (0)

#ifdef _WIN32
/* All components modulo-bounded: GCC 16 -Wformat-truncation treats raw WORD
 * fields as up to 5 digits (T10 round 1 finding). */
static void st_utc_rfc3339(char out[32])
{
    SYSTEMTIME st;
    GetSystemTime(&st);
    snprintf(out, 32, "%04u-%02u-%02uT%02u:%02u:%02u.%03uZ",
             (unsigned)st.wYear % 10000u, (unsigned)st.wMonth % 100u,
             (unsigned)st.wDay % 100u, (unsigned)st.wHour % 100u,
             (unsigned)st.wMinute % 100u, (unsigned)st.wSecond % 100u,
             (unsigned)st.wMilliseconds % 1000u);
}
#else
/* civil_from_days (Howard Hinnant) — same bounded-arithmetic approach as
 * knlog.c/kn_diag.c; avoids -Wformat-truncation on tm field widths. */
static void st_civil_from_days(long long z, int *yy, unsigned *mm, unsigned *dd)
{
    long long era, y;
    unsigned long long doe, yoe, doy, mp;
    z += 719468;
    era = (z >= 0 ? z : z - 146096) / 146097;
    doe = (unsigned long long)(z - era * 146097);
    yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    y = (long long)yoe + era * 400;
    doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    mp = (5 * doy + 2) / 153;
    *dd = (unsigned)(doy - (153 * mp + 2) / 5 + 1);
    *mm = (unsigned)(mp < 10 ? mp + 3 : mp - 9);
    *yy = (int)(y + (*mm <= 2 ? 1 : 0));
}
static void st_utc_rfc3339(char out[32])
{
    struct timespec ts;
    long long days, rem;
    int y;
    unsigned m, d;
    clock_gettime(CLOCK_REALTIME, &ts);
    days = (long long)ts.tv_sec / 86400LL;
    rem = (long long)ts.tv_sec % 86400LL;
    if (rem < 0) { rem += 86400LL; days -= 1; }
    st_civil_from_days(days, &y, &m, &d);
    snprintf(out, 32, "%04d-%02u-%02uT%02u:%02u:%02u.%03uZ",
             y, m, d, (unsigned)(rem / 3600LL), (unsigned)((rem / 60LL) % 60LL),
             (unsigned)(rem % 60LL), (unsigned)(ts.tv_nsec / 1000000L) % 1000u);
}
#endif

/* Single-line JSON (the stdout contract is newline-delimited JSON lines;
 * the bundle's selftest.json is the same document). reason/evidence are
 * produced by this file and contain no quotes or control chars by
 * construction — evidence is JSON itself and is embedded verbatim. */
size_t kn_selftest_render_json(const kn_st_result *results, int n,
                               char *buf, size_t bufsz)
{
    size_t o = 0;
    int i, trunc = 0;
    char ts[32];
    if (!buf || bufsz == 0) return 0;
    st_utc_rfc3339(ts);
    ST_APP(buf, bufsz, o, &trunc, "{\"generated_utc\":\"%s\",\"count\":%d,\"results\":[",
           ts, n);
    for (i = 0; i < n; ++i) {
        const kn_st_result *r = &results[i];
        ST_APP(buf, bufsz, o, &trunc,
             "%s{\"name\":\"%s\",\"status\":\"%s\",\"gated\":%s,\"ms\":%lld,\"checks\":%d,"
               "\"failures\":%d,\"reason\":\"%s\",\"evidence\":%s}",
             i ? "," : "", r->name, kn_selftest_status_name(r->status),
             kn_selftest_is_gated(r->name) ? "true" : "false", r->ms,
             r->checks, r->failures,
               r->reason[0] ? r->reason : "",
               r->evidence[0] ? r->evidence : "{}");
    }
    ST_APP(buf, bufsz, o, &trunc, "],\"truncated\":%s}",
           trunc ? "true" : "false");
    return o;
}

/* ---------------------------------------------------- relevance (§7.7.4) */

static int hay_has(const char *hay, const char *needle)
{
    return strstr(hay, needle) != NULL;
}

size_t kn_selftest_render_relevant(const char *op, const char *code,
                                   char *buf, size_t bufsz)
{
    char hay[256];
    size_t i, hn = 0;
    kn_st_result results[K_REGISTRY_N];
    int n = 0, ran = 0;
    int want_fec = 0, want_srtp = 0, want_net = 0, want_clock = 0, want_console = 0;
    int want_video = 0;

    /* lowercase concat of op+code (bounded) */
    for (i = 0; op && op[i] && hn + 1 < sizeof hay; ++i)
        hay[hn++] = (char)(op[i] >= 'A' && op[i] <= 'Z' ? op[i] + 32 : op[i]);
    if (hn + 1 < sizeof hay) hay[hn++] = '|';
    for (i = 0; code && code[i] && hn + 1 < sizeof hay; ++i)
        hay[hn++] = (char)(code[i] >= 'A' && code[i] <= 'Z' ? code[i] + 32 : code[i]);
    hay[hn] = '\0';

    if (hay_has(hay, "srtp") || hay_has(hay, "auth") || hay_has(hay, "crypt") ||
        hay_has(hay, "kdf") || hay_has(hay, "roc"))
        want_srtp = 1;
    if (hay_has(hay, "fec") || hay_has(hay, "shard") || hay_has(hay, "repair") ||
        hay_has(hay, "video") || hay_has(hay, "decode") || hay_has(hay, "garbl") ||
        hay_has(hay, "corrupt"))
        want_fec = 1;
    /* NOTE: no bare "rtp" keyword — it substring-matches inside "srtp" and
     * would drag the video battery into every SRTP failure. The transport
     * terms below are unambiguous. */
    if (hay_has(hay, "video") || hay_has(hay, "decode") || hay_has(hay, "garbl") ||
        hay_has(hay, "corrupt") || hay_has(hay, "d3d") || hay_has(hay, "present") ||
        hay_has(hay, "stretch") || hay_has(hay, "gpu") || hay_has(hay, "nack") ||
        hay_has(hay, "reorder") || hay_has(hay, "reassemb") || hay_has(hay, "pli") ||
        hay_has(hay, "loopback"))
        want_video = 1;
    if (hay_has(hay, "dns") || hay_has(hay, "tcp") || hay_has(hay, "tls") ||
        hay_has(hay, "net") || hay_has(hay, "http") || hay_has(hay, "wss"))
        want_net = 1;
    if (hay_has(hay, "clock") || hay_has(hay, "timer") || hay_has(hay, "jitter") ||
        hay_has(hay, "pacing"))
        want_clock = 1;
    if (hay_has(hay, "console") || hay_has(hay, "tui") || hay_has(hay, "vt") ||
        hay_has(hay, "ansi"))
        want_console = 1;
    if (!want_fec && !want_srtp && !want_net && !want_clock && !want_console &&
        !want_video) {
        want_fec = 1;             /* default: the two cheap offline proofs */
        want_srtp = 1;
    }

    for (i = 0; i < (size_t)K_REGISTRY_N && n < K_REGISTRY_N; ++i) {
        const char *nm = k_registry[i].name;
        int take = 0;
        if (want_fec && strcmp(nm, "fec.vectors") == 0) take = 1;
        if (want_srtp && strcmp(nm, "srtp.vectors") == 0) take = 1;
        if (want_video && (strcmp(nm, "decode.synthetic") == 0 ||
                           strcmp(nm, "d3d.formats") == 0 ||
                           strcmp(nm, "d3d.present") == 0 ||
                           strcmp(nm, "gs.parse") == 0))
            take = 1;
        if (want_net && (strncmp(nm, "net.", 4) == 0 || strcmp(nm, "tls.chain") == 0))
            take = 1;
        if (want_clock && strcmp(nm, "clock.resolution") == 0) take = 1;
        if (want_console && strcmp(nm, "console.host") == 0) take = 1;
        if (take && kn_selftest_run(nm, &results[n]) == 0) { ++n; ++ran; }
    }
    (void)ran;
    return kn_selftest_render_json(results, n, buf, bufsz);
}
